<?php
namespace Agah\Erp\Modules\Assets;
use Agah\Erp\Core\{Access,Audit,Business,Ctx,Db,Jalali,Money,Request,ValidationException,ConflictException};
use Agah\Erp\Modules\Accounting\{FiscalService,VoucherService};
use Agah\Erp\Modules\Payroll\PayrollService;
if(!defined('ABSPATH'))exit;
final class AssetService {
    private static function account($cid,$id,array $classes){$a=Business::row('accounts',$cid,Business::id($id));if(!$a['is_active']||(int)$a['level']!==3||!in_array($a['stmt_class'],$classes,true))throw new ValidationException(['account'=>'حساب فعال و متناسب انتخاب کنید.']);return $a;}
    private static function line($a,$amount,$debit,$detail=0){return ['account_id'=>(int)$a['id'],'detail_id'=>(int)$detail,'debit'=>$debit?$amount:0,'credit'=>$debit?0:$amount];}
    private static function plain($cid,$id,array $classes){$a=self::account($cid,$id,$classes);if($a['detail_rule']==='required')throw new ValidationException(['account'=>'حساب بدون تفصیلی اجباری انتخاب کنید.']);return $a;}
    private static function event($cid,$asset,$kind,$date,$amount,$lines,$extra=[]){$id=Business::save('asset_events',$cid,0,['asset_id'=>$asset,'kind'=>$kind,'doc_date'=>$date,'amount'=>$amount,'snapshot'=>wp_json_encode($extra)]+array_intersect_key($extra,array_flip(['period_key','proceeds','account_id','detail_id'])));$vid=null;if($lines)$vid=VoucherService::postSystem(['voucher_date'=>$date,'description'=>'دارایی #'.$asset.' '.$kind,'source_type'=>'asset_'.$kind,'source_id'=>$id],$lines);Db::update('asset_events',['voucher_id'=>$vid],['company_id'=>$cid,'id'=>$id]);Audit::log('asset.'.$kind,'asset_event',$id,null,['asset_id'=>$asset,'amount'=>$amount,'voucher_id'=>$vid],$cid);return $id;}
    public static function acquire($cid,array $in){return Access::write($cid,'asset.create',function()use($cid,$in){$date=Business::date($in['acquired_date']??'');$start=Business::date($in['start_date']??'');FiscalService::assertOpen($cid,$date);$name=Request::clean($in['name']??'',190);$code=Request::clean($in['code']??'',30);if(mb_strlen($name)<2||!preg_match('/^[A-Za-z0-9_-]{1,30}$/D',$code)||$start<$date)throw new ValidationException(['asset'=>'نام، کد یا تاریخ بهره‌برداری نامعتبر است.']);if(Db::val('SELECT id FROM '.Db::t('assets').' WHERE company_id=%d AND code=%s',$cid,$code))throw new ValidationException(['code'=>'کد تکراری است.']);$cost=Business::amount($in['cost']??null,true);$residual=Business::amount($in['residual']??null);$method=$in['method']??'';$life=$in['life_months']??null;$bp=$in['annual_bp']??null;AssetMath::depreciation($cost,$residual,0,$method,$life,$bp,1);
        $asset=self::plain($cid,$in['asset_account_id']??0,['asset_noncurrent']);$contra=self::plain($cid,$in['contra_account_id']??0,['contra_asset']);$expense=self::plain($cid,$in['expense_account_id']??0,['opex','other_expense']);$against=self::account($cid,$in['account_id']??0,['asset_current','liability_current','equity']);$did=Business::id($in['detail_id']??0);
        $data=['code'=>$code,'name'=>$name,'acquired_date'=>$date,'start_date'=>$start,'cost'=>$cost,'residual'=>$residual,'method'=>$method,'life_months'=>$life,'annual_bp'=>$bp,'asset_account_id'=>(int)$asset['id'],'contra_account_id'=>(int)$contra['id'],'expense_account_id'=>(int)$expense['id']];$id=Business::save('assets',$cid,0,$data);self::event($cid,$id,'purchase',$date,$cost,[self::line($asset,$cost,true),self::line($against,$cost,false,$did)],['account_id'=>(int)$against['id'],'detail_id'=>$did?:null]);return $id;});}
    public static function get($cid,$id){Access::need($cid,'asset.view');$r=Business::row('assets',$cid,$id);$r['events']=Db::rows('SELECT * FROM '.Db::t('asset_events').' WHERE company_id=%d AND asset_id=%d ORDER BY id',$cid,$id);$r['accum']=(int)Db::val('SELECT COALESCE(SUM(amount),0) FROM '.Db::t('asset_events')." WHERE company_id=%d AND asset_id=%d AND kind='depreciation' AND status='issued'",$cid,$id);$r['book_value']=(int)$r['cost']-$r['accum'];return $r;}
    private static function monthIndex($date){[$y,$m]=Jalali::fromDb($date);return $y*12+$m-1;}
    public static function depreciate($cid,$id,$period){return Access::write($cid,'asset.approve',function()use($cid,$id,$period){$a=self::get($cid,$id);if($a['status']!=='active')throw new ConflictException('دارایی فعال لازم است.');[$key,$start,$end]=PayrollService::period($period);FiscalService::assertOpen($cid,$end);$index=self::monthIndex($end);$first=self::monthIndex($a['start_date']);$n=(int)Db::val('SELECT COUNT(*) FROM '.Db::t('asset_events')." WHERE company_id=%d AND asset_id=%d AND kind='depreciation' AND status='issued'",$cid,$id);if($index!==$first+$n)throw new ConflictException('استهلاک باید از ماه بهره‌برداری و بدون تکرار یا فاصله صادر شود.');$month=$n+1;if($month>(int)$a['life_months']||$a['method']==='none')throw new ConflictException('این دارایی استهلاک قابل صدور ندارد.');$amount=AssetMath::depreciation((int)$a['cost'],(int)$a['residual'],$a['accum'],$a['method'],(int)$a['life_months'],(int)$a['annual_bp'],$month);$lines=[];if($amount){$expense=self::plain($cid,$a['expense_account_id'],['opex','other_expense']);$contra=self::plain($cid,$a['contra_account_id'],['contra_asset']);$lines=[self::line($expense,$amount,true),self::line($contra,$amount,false)];}return self::event($cid,$id,'depreciation',$end,$amount,$lines,['period_key'=>$key,'month'=>$month,'book_before'=>$a['book_value']]);});}
    public static function dispose($cid,$id,array $in){return Access::write($cid,'asset.approve',function()use($cid,$id,$in){$a=self::get($cid,$id);if($a['status']!=='active')throw new ConflictException('دارایی فعال لازم است.');$date=Business::date($in['doc_date']??'');FiscalService::assertOpen($cid,$date);if($date<$a['acquired_date'])throw new ValidationException(['date'=>'واگذاری قبل از خرید مجاز نیست.']);$last=Db::val('SELECT MAX(doc_date) FROM '.Db::t('asset_events')." WHERE company_id=%d AND asset_id=%d AND kind='depreciation' AND status='issued'",$cid,$id);$months=max(0,min((int)$a['life_months'],self::monthIndex($date)-self::monthIndex($a['start_date'])));$n=(int)Db::val('SELECT COUNT(*) FROM '.Db::t('asset_events')." WHERE company_id=%d AND asset_id=%d AND kind='depreciation' AND status='issued'",$cid,$id);if($a['method']!=='none'&&($n!==$months||($last&&$last>=$date)))throw new ConflictException('استهلاک ماه‌های قبل را کامل کنید؛ ماه واگذاری استهلاک نمی‌گیرد.');$proceeds=Business::amount($in['proceeds']??null);$against=self::account($cid,$in['account_id']??0,['asset_current']);$did=Business::id($in['detail_id']??0);$asset=self::plain($cid,$a['asset_account_id'],['asset_noncurrent']);$contra=self::plain($cid,$a['contra_account_id'],['contra_asset']);$lines=[];if($proceeds)$lines[]=self::line($against,$proceeds,true,$did);if($a['accum'])$lines[]=self::line($contra,$a['accum'],true);$lines[]=self::line($asset,(int)$a['cost'],false);$gain=$proceeds-$a['book_value'];if($gain){$pl=self::plain($cid,$in['result_account_id']??0,$gain>0?['other_income']:['other_expense']);$lines[]=self::line($pl,abs($gain),$gain<0);}$event=self::event($cid,$id,'disposal',$date,$a['book_value'],$lines,['proceeds'=>$proceeds,'account_id'=>(int)$against['id'],'detail_id'=>$did?:null,'gain'=>$gain]);Db::update('assets',['status'=>'disposed'],['company_id'=>$cid,'id'=>$id]);AssetCustodyService::endOnDisposal($cid,$id,$date);return $event;});}
    public static function voidEvent($cid,$event,$reason){return Access::write($cid,'asset.delete',function()use($cid,$event,$reason){$e=Business::row('asset_events',$cid,$event,true);if($e['status']!=='issued')throw new ConflictException('رویداد صادرشده لازم است.');$last=(int)Db::val('SELECT MAX(id) FROM '.Db::t('asset_events')." WHERE company_id=%d AND asset_id=%d AND status='issued'",$cid,$e['asset_id']);if($last!==(int)$event)throw new ConflictException('فقط آخرین رویداد فعال قابل ابطال است.');$reason=Business::reason($reason);FiscalService::assertOpen($cid,$e['doc_date']);if($e['voucher_id'])VoucherService::voidSystem((int)$e['voucher_id'],$reason);Db::update('asset_events',['status'=>'void','active_slot'=>null],['company_id'=>$cid,'id'=>$event]);Db::update('assets',['status'=>$e['kind']==='purchase'?'void':'active'],['company_id'=>$cid,'id'=>$e['asset_id']]);Audit::log('asset.void','asset_event',$event,['status'=>'issued'],['reason'=>$reason],$cid);});}
    public static function page($cid,$page=1,$q=''){Access::need($cid,'asset.view');$r=Business::page('assets',$cid,$page,$q);foreach($r['rows'] as &$a){$a['accum']=(int)Db::val('SELECT COALESCE(SUM(amount),0) FROM '.Db::t('asset_events')." WHERE company_id=%d AND asset_id=%d AND kind='depreciation' AND status='issued'",$cid,$a['id']);$a['book_value']=(int)$a['cost']-$a['accum'];}unset($a);return $r;}
}
